    'muted failed tests': ('/app/rest/testOccurrences', {'locator': f'build:(id:{build}),status:FAILURE,muted:true,count:20', 'fields': 'count,nextHref,testOccurrence(id,name,status,muted,ignored,details,build(id),test(id))'}),
    'changes': ('/app/rest/changes', {'locator': f'build:(id:{build}),count:10', 'fields': 'count,nextHref,change(id,version,username,date,comment)'}),
    'dependency count': (f'/app/rest/builds/id:{build}', {'fields': 'id,snapshot-dependencies(count)'}),
}
def redact(s):
    return re.sub(r'(?i)((?:authorization\s*[:=]\s*(?:bearer\s+)?|(?:password|passwd|token|secret|api[_-]?key)\s*[:=]\s*))[\w./+\-=]+', r'\1[REDACTED]', s)
def run(item):
    label, (path, params) = item
    target = path + '?' + urllib.parse.urlencode(params)
    p = subprocess.run(['teamcity', 'api', target, '-X', 'GET', '--raw', '-H', 'Accept: application/json', '--no-input'], text=True, capture_output=True)
    return {'source': label, 'exit_code': p.returncode, 'stdout': redact(p.stdout), 'stderr': redact(p.stderr)}
def log_tail():
    p = subprocess.run(['teamcity', 'run', 'log', build, '--tail', '80', '--json', '--no-input'], text=True, capture_output=True)
    return {'source': 'bounded log tail', 'exit_code': p.returncode, 'stdout': redact(p.stdout), 'stderr': redact(p.stderr)}
with concurrent.futures.ThreadPoolExecutor(max_workers=6) as pool:
    futures = [pool.submit(run, item) for item in requests.items()] + [pool.submit(log_tail)]
    for future in concurrent.futures.as_completed(futures):
        print(json.dumps(future.result()))
