import json, subprocess, concurrent.futures, urllib.parse
requests=[]
for bid in [482190,482191]:
 paths={
  'dependency_count':f'/app/rest/builds/id:{bid}?'+urllib.parse.urlencode({'fields':'id,snapshot-dependencies(count)'}),
  'immediate_dependencies':'/app/rest/builds?'+urllib.parse.urlencode({'locator':f'snapshotDependency:(to:(id:{bid}),recursive:false),defaultFilter:false,count:20','fields':'count,nextHref,build(id,buildTypeId,state,status,buildType(id,projectId))'}),
  'problems':'/app/rest/problemOccurrences?'+urllib.parse.urlencode({'locator':f'build:(id:{bid}),count:20','fields':'count,nextHref,problemOccurrence(id,type,identity,details,build(id))'}),
  'tests_unmuted':'/app/rest/testOccurrences?'+urllib.parse.urlencode({'locator':f'build:(id:{bid}),status:FAILURE,muted:false,count:20','fields':'count,nextHref,testOccurrence(id,name,status,muted,ignored,details,build(id),test(id))'}),
  'tests_muted':'/app/rest/testOccurrences?'+urllib.parse.urlencode({'locator':f'build:(id:{bid}),status:FAILURE,muted:true,count:20','fields':'count,nextHref,testOccurrence(id,name,status,muted,ignored,details,build(id),test(id))'}),
  'changes':'/app/rest/changes?'+urllib.parse.urlencode({'locator':f'build:(id:{bid}),count:10','fields':'count,nextHref,change(id,version,username,date,comment)'})}
 for label,path in paths.items(): requests.append((bid,label,['teamcity','api',path,'-X','GET','--raw','-H','Accept: application/json','--no-input']))
 requests.append((bid,'log_tail_80',['teamcity','run','log',str(bid),'--tail','80','--json','--no-input']))
def run(item):
 bid,label,cmd=item
 p=subprocess.run(cmd,text=True,capture_output=True)
 try: body=json.loads(p.stdout)
 except json.JSONDecodeError: body=p.stdout
 return {'execution':bid,'source':label,'exit_code':p.returncode,'body':body,'stderr':p.stderr}
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
 for result in pool.map(run,requests): print(json.dumps(result))
